settings.custom_css:
&, & img {
  object-fit: contain;
  height: 145px;
}
@media (min-width: 920px) {
  &, & img {
    object-fit: contain;
    height: 470px;
  }
}
@media (min-width: 1700px) {
  &,
  & img {
    height: 500px;
  }
}

.content-builder__title{
  font-weight:400;
  text-transform:unset;
  margin-top:16px;
  margin-bottom:0;
  text-align:center;
  max-width:unset;
  padding:0 5px;
}
.content-builder__content {
  margin-bottom: 0;
  text-align: center;
  max-width: unset;
  padding: 0 5px;
}
@media (min-width: 920px) {
  .content-builder__title {
    margin-top:10px;
    max-width: 31rem;
    text-align: center;
    line-height:1.3;
    margin-left: auto;
    margin-right: auto;
  }
  .content-builder__content {
    max-width: 30rem;
    line-height:1.3;
    margin: auto;
  }
}

