& a {
  text-transform: uppercase;
  border: 2px solid #b68b32;
  height:50px;
  width:185px;
   font-size: 14px !important;
   padding: 0 !important;
}
@media (min-width: 920px) {
  &  {
    margin-top:8px !important;
  }
  &  a{
    margin-bottom:0 !important;
  }
}

#SECTION_ID .content-builder__left{
  width: 100%;
  background:white;
  max-width: 56rem;
